extraCss:
/* Dublin piggyback hero: portrait source — push the cover anchor
   down so both faces survive the zoom */
.hero--bleed{--hero-focus:50% 38%;}
.guidance--calm .art-photo.taper-watch-photo img{object-position:45% 32%;}
.guidance--calm .art-photo.taper-postsession-photo img{object-position:60% 22%;}
@media(max-width:600px){.guidance--calm .art-photo.taper-watch-photo img{object-position:45% 30%;}.guidance--calm .art-photo.taper-postsession-photo img{object-position:60% 20%;}}
